import React from "react";
import { Link } from "react-router-dom";
import { HERO_ROLES } from "./roles";

/* Caption and role dots over the Experience hero logo, shared by
   LogoParticles and LogoParticlesLite. */

export function RoleCaption({ role, idx }) {
  if (!role) return null;
  return (
    <div key={`c${idx}`} className="xh-caption is-on is-auto">
      <span>
        <b>{role.title}</b> · {role.company} · {role.duration}
      </span>
      {role.shipped?.length > 0 && (
        <span className="xh-shipped">
          Shipped:{" "}
          {role.shipped.map((p, i) => (
            <React.Fragment key={p.slug}>
              {i > 0 && " · "}
              <Link to={`/projects/${p.slug}`}>{p.name}</Link>
            </React.Fragment>
          ))}
        </span>
      )}
    </div>
  );
}

// The active dot fills as its role plays: the renderer scales `fillRef`.
export function RoleDots({ idx, onJump, fillRef }) {
  return (
    <ol className="xh-dots">
      {HERO_ROLES.map((r, i) => (
        <li key={r.company}>
          <button
            type="button"
            className={i === idx ? "is-on" : ""}
            style={{ "--c": r.color }}
            onClick={() => onJump(i)}
            aria-label={`${r.title}, ${r.company}`}
          >
            {i === idx && <i ref={fillRef} />}
          </button>
        </li>
      ))}
    </ol>
  );
}
