import React, { useCallback, useEffect, useRef, useState } from "react";
import { HERO_ROLES, loadImage } from "./roles";
import { hexToRgb, sampleLogo } from "./logoSampler";
import { RoleCaption, RoleDots } from "./RoleOverlay";

/* ==========================================================
   EXPERIENCE HERO · LOGO PARTICLES (LITE)
   The phone version of LogoParticles: the same logos, order, vortex
   morph, landing and light sweep, drawn on a plain 2D canvas with ~1.6k
   points and no three.js. The orbit ring and halo are flat 2D shapes.
   It pauses off screen and in background tabs.

   Interaction
   - touch / pointer: particles part and brighten round the finger
   - role dots: jump to a role; the active dot fills as the role plays
   ========================================================== */

const COUNT = 1600;
const HOLD = 4.2; // seconds a logo holds
const MORPH = 1.6; // seconds of vortex between logos
const CYCLE = HOLD + MORPH;
const FIT = { w: 6.6, h: 2.9, y: 0.3 }; // logo box, world units (as desktop)
const LAND = 0.7; // seconds the left-to-right landing sweep takes
const SWEEP = { at: 1.3, dur: 1.5 }; // light band across the formed logo

export default function LogoParticlesLite({ light = false, figure = null }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const dotFillRef = useRef(null);
  const [idx, setIdx] = useState(0);
  const ctl = useRef({ jump: -1, light });
  ctl.current.light = light;

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    const g = canvas?.getContext("2d");
    if (!g || !wrap) return undefined;
    let alive = true;
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")
      .matches;
    const cols = HERO_ROLES.map((r) => hexToRgb(r.color));
    const hue = { ...cols[0] };

    // ---- sizing: world units → CSS px ----
    let w = 0;
    let h = 0;
    let k = 1; // px per world unit
    let ox = 0;
    let oy = 0;
    const resize = () => {
      w = wrap.clientWidth;
      h = wrap.clientHeight;
      if (!w || !h) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      g.setTransform(dpr, 0, 0, dpr, 0, 0);
      k = Math.min((w * 0.94) / FIT.w, (h * 0.62) / FIT.h);
      ox = w / 2;
      oy = h * 0.47;
    };
    resize();
    let rz = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(rz);
      rz = requestAnimationFrame(resize);
    });
    ro.observe(wrap);

    // ---- particles (world units), scattered on a disc to start ----
    const px = new Float32Array(COUNT);
    const py = new Float32Array(COUNT);
    const pc = new Float32Array(COUNT * 3).fill(0.6);
    const rnd = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      rnd[i] = Math.random();
      const a = Math.random() * Math.PI * 2;
      const r = 2 + Math.random() * 3;
      px[i] = Math.cos(a) * r;
      py[i] = Math.sin(a) * r * 0.5;
    }

    let targets = null;
    Promise.all(HERO_ROLES.map((r) => loadImage(r.logo))).then((imgs) => {
      if (!alive) return;
      targets = imgs.map((img, i) =>
        img
          ? sampleLogo(img, cols[i], HERO_ROLES[i].edits, {
              count: COUNT,
              fit: FIT,
            })
          : null
      );
    });

    // ---- touch / pointer ----
    const hand = { x: 99, y: 99 };
    const onMove = (e) => {
      const r = canvas.getBoundingClientRect();
      hand.x = (e.clientX - r.left - ox) / k;
      hand.y = -(e.clientY - r.top - oy) / k;
    };
    const onLeave = () => {
      hand.x = 99;
      hand.y = 99;
    };
    wrap.addEventListener("pointermove", onMove);
    wrap.addEventListener("pointerdown", onMove);
    wrap.addEventListener("pointerup", onLeave);
    wrap.addEventListener("pointercancel", onLeave);
    wrap.addEventListener("pointerleave", onLeave);

    // ---- loop ----
    let raf = 0;
    let visible = true;
    let last = performance.now();
    let t = 0;
    let cyc = 0;
    let shown = -1;
    const n = HERO_ROLES.length;
    const ch = (v) => Math.round(Math.min(1, Math.max(0, v)) * 255);

    const tick = (now) => {
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      t += dt;
      const lt = ctl.current.light;

      if (ctl.current.jump >= 0) {
        cyc = ctl.current.jump * CYCLE + 0.01;
        ctl.current.jump = -1;
      }
      if (!reduce) cyc += dt;
      const ki = Math.floor(cyc / CYCLE) % n;
      const phase = cyc % CYCLE;
      if (ki !== shown) {
        shown = ki;
        setIdx(ki);
      }
      if (dotFillRef.current)
        dotFillRef.current.style.transform = `scaleX(${Math.min(
          1,
          phase / CYCLE
        )})`;
      // the vortex unwinds into the next logo: swap targets at its peak
      const kk = phase > HOLD + MORPH * 0.5 ? (ki + 1) % n : ki;
      const hl = 1 - Math.exp(-dt * 3);
      hue.r += (cols[kk].r - hue.r) * hl;
      hue.g += (cols[kk].g - hue.g) * hl;
      hue.b += (cols[kk].b - hue.b) * hl;
      const hueCss = (a) => `rgba(${ch(hue.r)},${ch(hue.g)},${ch(hue.b)},${a})`;

      g.clearRect(0, 0, w, h);

      // soft halo + orbit ring with its comet (flat stand-ins for the 3D ones)
      const rx = Math.min(3.9 * k, w * 0.47);
      const ry = rx * 0.2;
      const cy = oy + 0.1 * k;
      const halo = g.createRadialGradient(ox, oy, 0, ox, oy, rx);
      halo.addColorStop(0, hueCss(lt ? 0.1 : 0.16));
      halo.addColorStop(1, hueCss(0));
      g.fillStyle = halo;
      g.fillRect(0, 0, w, h);
      g.save();
      g.setLineDash([1.5, 5]);
      g.lineWidth = 1.2;
      g.strokeStyle = hueCss(lt ? 0.55 : 0.45);
      g.beginPath();
      g.ellipse(ox, cy, rx, ry, 0, 0, Math.PI * 2);
      g.stroke();
      g.restore();
      const ca = t * 0.9;
      const cx0 = ox + Math.cos(ca) * rx;
      const cy0 = cy + Math.sin(ca) * ry;
      const comet = g.createRadialGradient(cx0, cy0, 0, cx0, cy0, 14);
      comet.addColorStop(0, hueCss(0.9));
      comet.addColorStop(1, hueCss(0));
      g.fillStyle = comet;
      g.fillRect(cx0 - 14, cy0 - 14, 28, 28);

      // logo particles
      if (targets) {
        const tgt = targets[kk] || targets.find(Boolean);
        const burst =
          phase > HOLD ? Math.sin(((phase - HOLD) / MORPH) * Math.PI) : 0;
        const fast = reduce ? 1 : 1 - Math.exp(-dt * 6);
        const slow = 1 - Math.exp(-dt * 3);
        const land = 1 - Math.exp(-dt * 1.2);
        const sw = (phase - SWEEP.at) / SWEEP.dur;
        const sv = sw > 0 && sw < 1 && !reduce ? -6 + sw * 12 : -99;
        g.globalCompositeOperation = lt ? "source-over" : "lighter";
        for (let i = 0; i < COUNT; i++) {
          const i3 = i * 3;
          const i5 = i * 5;
          const r = rnd[i];
          let tx = tgt[i5];
          let ty = tgt[i5 + 1];
          if (burst > 0) {
            const a = Math.atan2(ty, tx) + burst * (2.2 + r * 2.5);
            const rr =
              Math.hypot(tx, ty) * (1 + burst * 0.5) + burst * (0.6 + r * 1.8);
            tx = Math.cos(a) * rr;
            ty = Math.sin(a) * rr * 0.55;
          }
          const landing =
            phase < LAND &&
            cyc > CYCLE &&
            !reduce &&
            tx / FIT.w + 0.5 > phase / LAND;
          const pull = landing ? land : phase > HOLD ? slow : fast;
          let x = px[i] + (tx - px[i]) * pull;
          let y = py[i] + (ty - py[i]) * pull;
          const dx = x - hand.x;
          const dy = y - hand.y;
          const d2 = dx * dx + dy * dy;
          if (d2 < 1.3) {
            const f = (1.3 - d2) * 0.14;
            x += dx * f;
            y += dy * f;
          }
          px[i] = x;
          py[i] = y;
          pc[i3] += (tgt[i5 + 2] - pc[i3]) * pull;
          pc[i3 + 1] += (tgt[i5 + 3] - pc[i3 + 1]) * pull;
          pc[i3 + 2] += (tgt[i5 + 4] - pc[i3 + 2]) * pull;

          // highlight from the sweep band and the finger
          const sx = x + y * 0.35 - sv;
          const b = Math.exp(-sx * sx * 3) + 0.7 * Math.exp(-d2 * 1.6);
          const twinkle = 0.85 + 0.15 * Math.sin(t * 2 + r * 30);
          const s = (1.2 + r * 1.4) * twinkle * (1 + b * 0.5);
          let cr = pc[i3];
          let cg = pc[i3 + 1];
          let cb = pc[i3 + 2];
          if (lt) {
            const m = 0.62 * (1 - 0.25 * b);
            cr *= m;
            cg *= m;
            cb *= m;
          } else {
            cr = cr * 0.75 + (cr * 0.9 + 0.22) * b;
            cg = cg * 0.75 + (cg * 0.9 + 0.22) * b;
            cb = cb * 0.75 + (cb * 0.9 + 0.22) * b;
          }
          g.fillStyle = `rgb(${ch(cr)},${ch(cg)},${ch(cb)})`;
          g.fillRect(ox + x * k - s / 2, oy - y * k - s / 2, s, s);
        }
        g.globalCompositeOperation = "source-over";
      }

      raf = visible && !document.hidden ? requestAnimationFrame(tick) : 0;
    };
    const start = () => {
      if (!raf && visible && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      start();
    });
    io.observe(wrap);
    document.addEventListener("visibilitychange", start);
    start();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      cancelAnimationFrame(rz);
      io.disconnect();
      ro.disconnect();
      document.removeEventListener("visibilitychange", start);
      wrap.removeEventListener("pointermove", onMove);
      wrap.removeEventListener("pointerdown", onMove);
      wrap.removeEventListener("pointerup", onLeave);
      wrap.removeEventListener("pointercancel", onLeave);
      wrap.removeEventListener("pointerleave", onLeave);
    };
  }, []);

  const jump = useCallback((i) => {
    ctl.current.jump = i;
  }, []);

  const role = HERO_ROLES[idx];
  return (
    <div
      ref={wrapRef}
      className="xh xh-particles xh-lite"
      style={{ "--c": role ? role.color : "#2962FF" }}
    >
      <canvas ref={canvasRef} aria-hidden="true" />
      {figure && <div className="xh-figure">{figure}</div>}
      <RoleCaption role={role} idx={idx} />
      <RoleDots idx={idx} onJump={jump} fillRef={dotFillRef} />
    </div>
  );
}
