/* Logo sampling shared by the Experience hero's two renderers
   (LogoParticles: three.js, desktop; LogoParticlesLite: 2D canvas, phones). */

const EDGE_SHARE = 0.5; // share of points placed on the logo's outline

// "#rrggbb" → { r, g, b } in 0..1 (same values as THREE.Color in three r135)
export const hexToRgb = (hex) => {
  const n = parseInt(String(hex).replace("#", ""), 16);
  return {
    r: ((n >> 16) & 255) / 255,
    g: ((n >> 8) & 255) / 255,
    b: (n & 255) / 255,
  };
};

// Sample a logo's ink pixels into `count` targets (x, y, r, g, b), fitted
// to the `fit` box (world units) and ordered by angle round the centre, so point i sits in the
// same direction in every logo and morphs travel short arcs.
export function sampleLogo(img, tint, edits = null, { count, fit }) {
  const W = 360;
  const s = W / img.width;
  const H = Math.max(1, Math.round(img.height * s));
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d", { willReadFrequently: true });
  g.drawImage(img, 0, 0, W, H);
  const rt = edits?.retext;
  if (rt) {
    // swap the wordmark: clear its box, set the new text to the box's cap height
    const [x0, y0, x1, y1] = [
      rt.box[0] * W,
      rt.box[1] * H,
      rt.box[2] * W,
      rt.box[3] * H,
    ];
    g.clearRect(x0, y0, x1 - x0, y1 - y0);
    let size = (y1 - y0) / 0.72;
    g.font = `600 ${size}px "Google Sans Medium", "Google Sans", sans-serif`;
    const tw = g.measureText(rt.text).width;
    if (tw > x1 - x0) {
      size *= (x1 - x0) / tw;
      g.font = `600 ${size}px "Google Sans Medium", "Google Sans", sans-serif`;
    }
    g.fillStyle = rt.color;
    g.textAlign = "center";
    g.textBaseline = "alphabetic";
    g.fillText(rt.text, (x0 + x1) / 2, y1);
  }
  const split = edits?.split && {
    at: edits.split.at,
    tint: hexToRgb(edits.split.color),
  };
  const d = g.getImageData(0, 0, W, H).data;
  // keep opaque ink; skip white and pale background
  const raw = new Uint8Array(W * H);
  for (let i = 0; i < W * H; i++)
    raw[i] =
      d[i * 4 + 3] > 120 && d[i * 4] + d[i * 4 + 1] + d[i * 4 + 2] < 540
        ? 1
        : 0;
  // minRun: drop strokes thinner than this many pixels in either direction
  // (the grid lines behind the CAMS letters)
  let mask = raw;
  const mr = edits?.minRun;
  if (mr) {
    const hRun = new Uint16Array(W * H);
    const vRun = new Uint16Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; ) {
        let e = x;
        while (e < W && raw[y * W + e]) e++;
        for (let i = x; i < e; i++) hRun[y * W + i] = e - x;
        x = e + 1;
      }
    }
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; ) {
        let e = y;
        while (e < H && raw[e * W + x]) e++;
        for (let i = y; i < e; i++) vRun[i * W + x] = e - y;
        y = e + 1;
      }
    }
    mask = raw.map((v, i) => (v && hRun[i] >= mr && vRun[i] >= mr ? 1 : 0));
  }
  const ink = (x, y) =>
    x >= 0 && y >= 0 && x < W && y < H && mask[y * W + x] === 1;
  const fill = [];
  const edge = [];
  let [bx0, by0, bx1, by1] = [W, H, 0, 0];
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      if (!ink(x, y)) continue;
      const k = (y * W + x) * 4;
      const h = [x, y, d[k], d[k + 1], d[k + 2]];
      fill.push(h);
      if (!ink(x - 1, y) || !ink(x + 1, y) || !ink(x, y - 1) || !ink(x, y + 1))
        edge.push(h);
      bx0 = Math.min(bx0, x);
      by0 = Math.min(by0, y);
      bx1 = Math.max(bx1, x);
      by1 = Math.max(by1, y);
    }
  }
  if (!fill.length) [bx0, by0, bx1, by1] = [0, 0, W, H];
  const cx = (bx0 + bx1) / 2;
  const cy = (by0 + by1) / 2;
  const scale = Math.min(
    fit.w / Math.max(1, bx1 - bx0),
    fit.h / Math.max(1, by1 - by0)
  );
  // the logo's own colour pulled toward the role colour, so dark and
  // grey logos still glow on a dark page; outline points a touch brighter
  const mix = (v, t, lift) => Math.min(1, ((v / 255) * 0.35 + t * 0.85) * lift);
  const pts = [];
  for (let i = 0; i < count; i++) {
    const onEdge = edge.length && Math.random() < EDGE_SHARE;
    const pool = onEdge ? edge : fill;
    const h = pool.length
      ? pool[Math.floor(Math.random() * pool.length)]
      : [cx, cy, 200, 200, 200];
    const x = (h[0] + (Math.random() - 0.5) * 0.6 - cx) * scale;
    const y = -(h[1] + (Math.random() - 0.5) * 0.6 - cy) * scale + fit.y;
    const tc = split && h[0] >= split.at * W ? split.tint : tint;
    const lift = onEdge ? 1.15 : 0.9;
    pts.push([
      Math.atan2(y - fit.y, x * 0.45),
      x,
      y,
      mix(h[2], tc.r, lift),
      mix(h[3], tc.g, lift),
      mix(h[4], tc.b, lift),
    ]);
  }
  pts.sort((a, b) => a[0] - b[0]);
  const out = new Float32Array(count * 5);
  pts.forEach((p, i) => out.set(p.slice(1), i * 5));
  return out;
}
