import { experience, projects } from "../../../portfolio.js";

/* The work roles, current role first, with their logo files resolved and the
   projects shipped in each, for the Experience hero visuals. */

const work = (
  (experience.sections || []).find((s) => s.title === "Work") || {
    experiences: [],
  }
).experiences;

// Projects shipped in each role, keyed by the role's logo file.
const ROLE_PROJECTS = {
  "assist.png": [
    "ravi-visual-assistant",
    "table-recognition-system",
    "ravi-accessible-stem-education",
  ],
  "cams.png": ["cams-lens", "ai-email-automation"],
  "Think_logo.png": ["camscode", "intelligent-document-processing"],
};

// Per-logo edits for the particles (fractions of the logo image):
// - split: ink right of `at` takes its own colour. AssisTech stays in the
//   role's green, the IIT Delhi half glows in IIT red.
// - retext: the wordmark in `box` is redrawn as `text` (the image has it
//   in lowercase).
// - minRun: strokes thinner than this (px, at sampling size) are dropped,
//   which removes the grid behind the CAMS letters.
const LOGO_EDITS = {
  "cams.png": { minRun: 3 },
  "assist.png": {
    split: { at: 0.55, color: "#E53935" },
    retext: {
      box: [0.63, 0.575, 0.965, 0.66],
      text: "IIT Delhi",
      color: "#001c44",
    },
  },
};

const logoUrl = (file) => {
  try {
    const m = require(`../../../assests/images/${file}`);
    return m.default || m;
  } catch (e) {
    return null;
  }
};

const projectBySlug = Object.fromEntries(
  ((projects && projects.data) || []).map((p) => [p.slug, p])
);

// Short display names for the "Shipped" line (the project titles in
// portfolio.js are long and some share a prefix, e.g. "RAVI - …").
const SHORT_NAMES = {
  "ravi-visual-assistant": "RAVI Visual Assistant",
  "table-recognition-system": "Table Recognition",
  "ravi-accessible-stem-education": "Accessible STEM",
  "cams-lens": "CAMS Lens",
  "ai-email-automation": "AI Email Automation",
  camscode: "CAMSCode",
  "intelligent-document-processing": "Document Processing",
};
const shippedFor = (logoFile) =>
  (ROLE_PROJECTS[logoFile] || [])
    .filter((slug) => projectBySlug[slug])
    .map((slug) => ({ slug, name: SHORT_NAMES[slug] || slug }));

// The four main roles (skip the short project entry), current role first.
export const HERO_ROLES = work
  .filter((r) => !/project/i.test(r.title) && !/intern/i.test(r.title))
  .slice(0, 4)
  .map((r) => ({
    title: r.title,
    company: r.company,
    duration: r.duration,
    color: r.color || "#2962FF",
    logo: logoUrl(r.logo_path),
    edits: LOGO_EDITS[r.logo_path] || null,
    shipped: shippedFor(r.logo_path),
  }));

export const loadImage = (src) =>
  new Promise((resolve) => {
    if (!src) return resolve(null);
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
