import React, { lazy, Suspense, useEffect, useRef, useState } from "react";
import Header from "../../components/header/Header";
import Footer from "../../components/footer/Footer";
import ExperienceAccordion from "../../containers/experienceAccordion/ExperienceAccordion.js";
import "./Experience.css";
import { experience } from "../../portfolio.js";
import { Fade } from "react-reveal";
import ExperienceImg from "./ExperienceImg";
import { Link } from "react-router-dom";
import LogoParticlesLite from "./hero3d/LogoParticlesLite";
import { greeting } from "../../portfolio.js";
import "./hero3d/hero3d.css";

// three.js stays out of this page's first download: the desktop logo scene
// and the 3D title mark load after the page paints (phones never fetch the
// logo scene at all).
const LogoParticles = lazy(() => import("./hero3d/LogoParticles"));
const GrowthMark = lazy(() => import("./GrowthMark"));

// Section accents: [bright for dark theme, deep for light theme]
const SECTION_CHIP_COLORS = {
  Work: ["#4d8aff", "#2962FF"],
  Internships: ["#FFA726", "#EF6C00"],
  Volunteerships: ["#00E676", "#00A152"],
};

function Experience(props) {
  const theme = props.theme;
  const heroRef = useRef(null);

  // Current role — first "Present" entry in the Work section
  const workSection = (experience.sections || []).find(
    (s) => s.title === "Work"
  );
  const currentRole = workSection?.experiences?.find((e) =>
    /present/i.test(e.duration || "")
  );
  // Desktop gets the three.js particle hero; phones and small tablets get
  // the lighter 2D-canvas version of it.
  const wideQuery = "(min-width: 900px)";
  const [wide, setWide] = useState(
    () => window.matchMedia?.(wideQuery).matches ?? true
  );
  useEffect(() => {
    const mq = window.matchMedia?.(wideQuery);
    if (!mq) return undefined;
    const on = () => setWide(mq.matches);
    mq.addEventListener
      ? mq.addEventListener("change", on)
      : mq.addListener(on);
    return () =>
      mq.removeEventListener
        ? mq.removeEventListener("change", on)
        : mq.removeListener(on);
  }, []);

  // The illustration drifts a few px toward the pointer (CSS vars only).
  useEffect(() => {
    const el = heroRef.current;
    if (!el || !window.matchMedia?.("(pointer: fine)").matches)
      return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    let raf = 0;
    let tx = 0;
    let ty = 0;
    let x = 0;
    let y = 0;
    const loop = () => {
      x += (tx - x) * 0.08;
      y += (ty - y) * 0.08;
      el.style.setProperty("--px", x.toFixed(3));
      el.style.setProperty("--py", y.toFixed(3));
      raf =
        Math.abs(tx - x) + Math.abs(ty - y) > 0.002
          ? requestAnimationFrame(loop)
          : 0;
    };
    const move = (e) => {
      tx = (e.clientX / window.innerWidth) * 2 - 1;
      ty = (e.clientY / window.innerHeight) * 2 - 1;
      if (!raf) raf = requestAnimationFrame(loop);
    };
    window.addEventListener("pointermove", move);
    return () => {
      window.removeEventListener("pointermove", move);
      cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <div className="experience-main" data-theme={theme?.name}>
      <Header theme={theme} setTheme={props.setTheme} />
      <div className="basic-experience">
        <Fade bottom duration={2000} distance="40px">
          <div className="experience-heading-div xh-hero">
            <div className="experience-heading-img-div has-3d" ref={heroRef}>
              {wide ? (
                <Suspense fallback={<div className="xh xh-particles" />}>
                  <LogoParticles
                    figure={<ExperienceImg theme={theme} />}
                    light={theme?.name === "light"}
                  />
                </Suspense>
              ) : (
                <LogoParticlesLite
                  figure={<ExperienceImg theme={theme} />}
                  light={theme?.name === "light"}
                />
              )}
            </div>
            <div className="experience-heading-text-div xh-text">
              <h1 className="experience-heading-text">
                {/* any trailing emoji in the title gives way to the 3D mark */}
                <span className="xh-word">
                  {String(experience.title)
                    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "")
                    .trim()}
                </span>
                <Suspense
                  fallback={
                    <span
                      className="exp-growth-mark"
                      style={{ width: 96, height: 96 }}
                      aria-hidden="true"
                    />
                  }
                >
                  <GrowthMark />
                </Suspense>
              </h1>
              <h3
                className="experience-heading-sub-text"
                style={{ color: theme.text }}
              >
                {experience["subtitle"]}
              </h3>
              <p
                className="experience-header-detail-text subTitle"
                style={{ color: theme.secondaryText }}
              >
                {experience["description"]}
              </p>

              {currentRole && (
                <div className="exp-current-pill">
                  <span className="exp-current-pulse" aria-hidden="true" />
                  Currently — {currentRole.title} · {currentRole.company}
                </div>
              )}

              <div className="exp-hero-chips">
                {(experience.sections || []).map((s) => {
                  const [bright, deep] = SECTION_CHIP_COLORS[s.title] || [
                    "#4d8aff",
                    "#2962FF",
                  ];
                  return (
                    <span
                      className="exp-hero-chip"
                      key={s.title}
                      style={{
                        "--chip-accent": bright,
                        "--chip-accent-deep": deep,
                      }}
                    >
                      <span className="exp-chip-dot" aria-hidden="true" />
                      <span className="exp-chip-count">
                        {s.experiences.length}
                      </span>{" "}
                      {s.title === "Work" ? "Work roles" : s.title}
                    </span>
                  );
                })}
              </div>

              <div className="xh-ctas">
                <Link to="/projects" className="xh-cta xh-cta-primary">
                  See the projects <span aria-hidden="true">→</span>
                </Link>
                {greeting.resumeLink && (
                  <a
                    href={greeting.resumeLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="xh-cta"
                  >
                    Résumé <span aria-hidden="true">↗</span>
                  </a>
                )}
              </div>
            </div>
          </div>
        </Fade>
      </div>
      <ExperienceAccordion sections={experience["sections"]} theme={theme} />
      <Footer theme={props.theme} onToggle={props.onToggle} />
    </div>
  );
}

export default Experience;
